// @name JSX: Weather
// @background #082f49
// @refresh 3600
// A week of (made up) weather: tap a day for its details. The icons are SVG
// inside the UI, colored by the text color (currentColor).
const Sun = ({ size }) => (
  <svg className={`${size} text-amber-400`} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round">
    <circle cx={12} cy={12} r={4} fill="currentColor" />
    <path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4" />
  </svg>
)
const Cloud = ({ size }) => (
  <svg className={`${size} text-slate-300`} viewBox="0 0 24 24">
    <path fill="currentColor" d="M7 18a5 5 0 0 1-.6-9.96A6 6 0 0 1 18 9a4.5 4.5 0 0 1-.5 9z" />
  </svg>
)
const Rain = ({ size }) => (
  <svg className={`${size} text-sky-400`} viewBox="0 0 24 24">
    <path fill="#cbd5e1" d="M7 14a5 5 0 0 1-.6-9.96A6 6 0 0 1 18 5a4.5 4.5 0 0 1-.5 9z" />
    <path stroke="currentColor" strokeWidth={2} strokeLinecap="round" d="M8 17l-1 3M12 17l-1 3M16 17l-1 3" />
  </svg>
)
const days = [
  { day: 'Mon', Icon: Sun, hi: 18, lo: 7, text: 'Sunny and still', wind: 6 },
  { day: 'Tue', Icon: Cloud, hi: 15, lo: 8, text: 'Grey, dry', wind: 12 },
  { day: 'Wed', Icon: Rain, hi: 11, lo: 6, rain: 12, text: 'Rain from noon', wind: 22 },
  { day: 'Thu', Icon: Rain, hi: 9, lo: 4, rain: 5, text: 'Showers', wind: 18 },
  { day: 'Fri', Icon: Cloud, hi: 12, lo: 3, text: 'Clouds clearing', wind: 9 },
  { day: 'Sat', Icon: Sun, hi: 16, lo: 5, text: 'Bright, cold start', wind: 7 },
  { day: 'Sun', Icon: Sun, hi: 19, lo: 9, text: 'Warm afternoon', wind: 5 },
]
let pick = 0

export function get(app) {
  const d = days[pick]
  return (
    <div className="flex flex-col gap-4 p-5 bg-sky-950 text-white">
      <div className="flex items-center gap-5 rounded-3xl bg-white/10 p-5">
        {d.Icon({ size: 'w-24 h-24' })}
        <div className="flex flex-col flex-1">
          <span className="text-lg text-sky-200">{pick === 0 ? 'Today' : d.day}</span>
          <span className="text-6xl font-bold">{`${d.hi}°`}</span>
          <span className="text-slate-300">{d.text}</span>
        </div>
        <div className="flex flex-col items-end gap-1 text-sm text-slate-300">
          <span>{`Low ${d.lo}°`}</span>
          <span>{`Wind ${d.wind} km/h`}</span>
          <span>{d.rain ? `Rain ${d.rain} mm` : 'No rain'}</span>
        </div>
      </div>
      <div className="flex-1 grid grid-cols-7 gap-2">
        {days.map((x, i) => (
          <div className={`flex flex-col items-center justify-center gap-2 rounded-2xl ${i === pick ? 'bg-white/25' : 'bg-white/5 active:bg-white/15'}`}
            onClick={() => { pick = i }}>
            <span className={`text-sm ${i === pick ? 'font-bold' : 'text-slate-300'}`}>{x.day}</span>
            {x.Icon({ size: 'w-9 h-9' })}
            <span className="text-lg font-semibold">{`${x.hi}°`}</span>
            <span className="text-sm text-slate-400">{`${x.lo}°`}</span>
          </div>
        ))}
      </div>
    </div>
  )
}
